package com.taller.portal.repository;
import com.taller.portal.dto.AdministracionClienteDtos.*; import com.taller.portal.model.Cliente; import java.time.LocalDate; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
/** Repositorio de clientes: cada lectura administrativa recibe taller obligatorio. */
public interface ClienteRepository extends JpaRepository<Cliente,Long>{
 @Query("select count(c)>0 from Cliente c where c.status.id=:statusId") boolean existeReferenciaStatus(@Param("statusId") Long statusId);
 /** Suspende una sola vez mediante condición atómica; devuelve cero ante carrera o suspensión previa. */
 @Modifying @Query("update Cliente c set c.status.id=:suspendido,c.isDeleted=true,c.deletedAt=CURRENT_TIMESTAMP,c.deletedBy.id=:usuarioId where c.id=:id and c.taller.id=:tallerId and c.isDeleted=false and c.status.id<>:suspendido") int suspenderAtomico(@Param("id") Long id,@Param("tallerId") Long tallerId,@Param("suspendido") Long suspendido,@Param("usuarioId") Long usuarioId);
 Optional<Cliente> findByIdempotencyKey(String key);
 boolean existsByEmailOrTelefonoPersonalOrTelefonoTrabajoOrNombreCompletoAndFechaNacimiento(String email,String personal,String trabajo,String nombre,LocalDate fecha);
 @Query("select (count(c)>0) from Cliente c where c.id<>:id and (c.email=:email or c.telefonoPersonal=:personal or c.telefonoTrabajo=:trabajo or (c.nombreCompleto=:nombre and c.fechaNacimiento=:fecha))") boolean duplicadoExcluyendo(@Param("id") Long id,@Param("email") String email,@Param("personal") String personal,@Param("trabajo") String trabajo,@Param("nombre") String nombre,@Param("fecha") LocalDate fecha);
 /** Comprueba correo repetido sin excluir expedientes soft-deleted. */ boolean existsByIdNotAndEmail(Long id,String email);
 /** Comprueba teléfono personal repetido sin excluir expedientes soft-deleted. */ boolean existsByIdNotAndTelefonoPersonal(Long id,String telefonoPersonal);
 /** Comprueba teléfono laboral repetido sin excluir expedientes soft-deleted. */ boolean existsByIdNotAndTelefonoTrabajo(Long id,String telefonoTrabajo);
 /** Comprueba identidad repetida sin excluir expedientes soft-deleted. */ boolean existsByIdNotAndNombreCompletoAndFechaNacimiento(Long id,String nombreCompleto,LocalDate fechaNacimiento);
 @Query("select new com.taller.portal.dto.AdministracionClienteDtos$Resumen(c.id,c.nombreCompleto,c.telefonoPersonal,c.email,c.municipio,c.taller.id,c.taller.nombre,c.status.strValor) from Cliente c where c.taller.id=:tallerId and c.isDeleted=false and (lower(c.nombreCompleto) like :patron escape '!' or lower(c.telefonoPersonal) like :patron escape '!' or lower(c.email) like :patron escape '!')") Page<Resumen> consultarPorTaller(@Param("tallerId") Long tallerId,@Param("patron") String patron,Pageable pagina);
 /** Lista incluso suspendidos con JOIN implícito a taller y status; Page ejecuta un conteo equivalente sin N+1. */
 @Query("select new com.taller.portal.dto.AdministracionClienteDtos$SuspensionResumen(c.id,c.nombreCompleto,c.telefonoPersonal,c.email,c.taller.id,c.taller.nombre,c.status.strValor,c.status.strDescripcion,c.isDeleted) from Cliente c where c.taller.id=:tallerId and (lower(c.nombreCompleto) like :patron escape '!' or lower(c.telefonoPersonal) like :patron escape '!' or lower(c.email) like :patron escape '!')") Page<SuspensionResumen> consultarSuspensionPorTaller(@Param("tallerId") Long tallerId,@Param("patron") String patron,Pageable pagina);
 @Query("select new com.taller.portal.dto.AdministracionClienteDtos$Detalle(c.id,c.nombreCompleto,c.contactoAlternativo,c.edad,c.fechaNacimiento,c.telefonoPersonal,c.telefonoTrabajo,c.email,c.emailTrabajo,c.calle,c.colonia,c.municipio,c.estado,c.codigoPostal,c.taller.id,c.taller.nombre,c.status.strValor) from Cliente c where c.id=:id and c.taller.id=:tallerId and c.isDeleted=false") Optional<Detalle> detallePorTaller(@Param("id") Long id,@Param("tallerId") Long tallerId);
 @Query("select c from Cliente c where c.id=:id and c.taller.id=:tallerId") Optional<Cliente> entidadPorTaller(@Param("id") Long id,@Param("tallerId") Long tallerId);
 @Query("select c.fotografiaRuta from Cliente c where c.id=:id and c.taller.id=:tallerId") Optional<String> rutaFotoPorTaller(@Param("id") Long id,@Param("tallerId") Long tallerId);
}
